summary:
Migrates the user schema to Zod 4 APIs while preserving exports, inferred types, validation behavior, and error messages.

```ts
import { z } from "zod";

export const User = z.object({
  name: z.string({
    error: (issue) =>
      issue.input === undefined ? "Name is required" : "Name must be text",
  }),
  tags: z.record(z.string()),
  ip: z
    .string()
    .refine(
      (value) => z.union([z.ipv4(), z.ipv6()]).safeParse(value).success,
      "Not an IP address",
    ),
});

export type User = z.infer<typeof User>;

export type ParseResult =
  | { ok: true; user: User }
  | { ok: false; errors: string[] };

export const parseUser = (input: unknown): ParseResult => {
  const result = User.safeParse(input);
  if (result.success) return { ok: true, user: result.data };
  return { ok: false, errors: result.error.issues.map((issue) => issue.message) };
};
```
